import { Prisma } from './generated/prisma/client';

await prisma.$transaction(async (tx) => {
  const from = await tx.account.update({
    where: { id: fromId },
    data: { balance: { decrement: amount } }
  });
  if (from.balance.lessThan(0)) {
    throw new Error('Insufficient funds'); // rolls back
  }
  await tx.account.update({
    where: { id: toId },
    data: { balance: { increment: amount } }
  });
  await tx.transfer.create({ data: { fromId, toId, amount } });
}, {
  isolationLevel: Prisma.TransactionIsolationLevel.Serializable,
  maxWait: 5000,
  timeout: 10000
});

// Safe: email becomes a bound parameter
const users = await prisma.$queryRaw<{ id: number; email: string }[]>`
  SELECT id, email FROM users WHERE email = ${email}
`;

// Dynamic IN list
const rows = await prisma.$queryRaw`
  SELECT * FROM products WHERE id IN (${Prisma.join(ids)})
`;

